  "check_code": "from pathlib import Path
import re
import sqlite3


CHANGE_ID = "CHG-SYS-2026-0732"
BACKUP_NAME = "state.db.pinned_backup"


def _db_path(ws):
    return Path(ws).parent / "system" / "servicenow_change_management" / "state.db"


def _backup_path(ws):
    return Path(ws).parent / "system" / "servicenow_change_management" / BACKUP_NAME


def _rows(path, query, params=()):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in connection.execute(query, params)]
    finally:
        connection.close()


def _task_projection(row):
    return tuple(row.get(key) for key in (
        "task_id", "change_id", "change_asset_id", "task_type", "task_status",
        "assigned_team_id", "assigned_to", "short_description", "completed_at",
        "evidence_ref",
    ))


def _asset_projection(row):
    return tuple(row.get(key) for key in (
        "change_asset_id", "change_id", "asset_id", "asset_name", "wave_number",
        "planned_start", "planned_end", "implementation_status", "exception_id",
        "rollout_note",
    ))


def check_created_parent_closure_task(ws):
    """Require exactly one new, open, parent-level closure task with the prescribed ownership."""
    current = _rows(
        _db_path(ws),
        "SELECT task_id, change_id, change_asset_id, task_type, task_status, "
        "assigned_team_id, assigned_to, short_description, completed_at, evidence_ref "
        "FROM change_tasks WHERE change_id = ? ORDER BY task_id",
        (CHANGE_ID,),
    )
    baseline = _rows(
        _backup_path(ws),
        "SELECT task_id, change_id, change_asset_id, task_type, task_status, "
        "assigned_team_id, assigned_to, short_description, completed_at, evidence_ref "
        "FROM change_tasks WHERE change_id = ? ORDER BY task_id",
        (CHANGE_ID,),
    )
    baseline_ids = {row["task_id"] for row in baseline}
    new_rows = [row for row in current if row["task_id"] not in baseline_ids]
    if len(new_rows) != 1:
        return {"score": 0, "detail": f"Expected one new task for {CHANGE_ID}; found {len(new_rows)}."}
    row = new_rows[0]
    description = re.sub(r"\s+", " ", str(row["short_description"] or "").strip().lower())
    required_phrases = (
        "cve-2026-20349",
        "post-implementation review",
    )
    missing = [phrase for phrase in required_phrases if phrase not in description]
    if not re.search(r"\b44\b", description):
        missing.append("44")
    if not re.search(r"\b3\b", description):
        missing.append("3")
    expected = {
        "change_id": CHANGE_ID,
        "change_asset_id": None,
        "task_type": "Closure",
        "task_status": "Open",
        "assigned_team_id": "TEAM-NMDS-SYSOPS",
        "assigned_to": "Daniel Brooks",
    }
    mismatches = {
        key: (row.get(key), value)
        for key, value in expected.items()
        if row.get(key) != value
    }
    if missing or mismatches or row.get("completed_at") not in (None, "") or row.get("evidence_ref") not in (None, ""):
        return {
            "score": 0,
            "detail": f"New task {row['task_id']} does not satisfy the required parent Closure state; "
                       f"missing description terms={missing}, mismatches={mismatches}.",
        }
    return {"score": 1, "detail": f"Created task {row['task_id']} has the required open parent Closure state."}


def check_preexisting_tasks_unchanged(ws):
    """Ensure the existing rollback task and every other historical task remain unchanged."""
    query = (
        "SELECT task_id, change_id, change_asset_id, task_type, task_status, assigned_team_id, "
        "assigned_to, short_description, completed_at, evidence_ref FROM change_tasks "
        "WHERE change_id = ? ORDER BY task_id"
    )
    current = _rows(_db_path(ws), query, (CHANGE_ID,))
    baseline = _rows(_backup_path(ws), query, (CHANGE_ID,))
    baseline_by_id = {row["task_id"]: _task_projection(row) for row in baseline}
    current_existing = {
        row["task_id"]: _task_projection(row)
        for row in current
        if row["task_id"] in baseline_by_id
    }
    if current_existing != baseline_by_id:
        return {"score": 0, "detail": "A pre-existing task under the change was modified or removed."}
    return {"score": 1, "detail": "All pre-existing tasks under the change are unchanged."}


def check_asset_assignments_unchanged(ws):
    """Ensure the 48 asset assignment rows, including the canceled duplicate, are unchanged."""
    query = (
        "SELECT change_asset_id, change_id, asset_id, asset_name, wave_number, planned_start, "
        "planned_end, implementation_status, exception_id, rollout_note FROM change_assets "
        "WHERE change_id = ? ORDER BY change_asset_id"
    )
    current = _rows(_db_path(ws), query, (CHANGE_ID,))
    baseline = _rows(_backup_path(ws), query, (CHANGE_ID,))
    current_projection = [_asset_projection(row) for row in current]
    baseline_projection = [_asset_projection(row) for row in baseline]
    if current_projection != baseline_projection:
        return {"score": 0, "detail": "Change asset assignments or implementation states changed."}
    if len(current_projection) != 48:
        return {"score": 0, "detail": f"Expected 48 change asset rows; found {len(current_projection)}."}
    return {"score": 1, "detail": "All 48 change asset assignments and states are unchanged."}
